import ast,json,hashlib
from pathlib import Path
p=json.load(open('proposal.json'));r=json.load(open('runtime.json'))
def check(x,s):
 if s.get('type')=='object':
  assert isinstance(x,dict) and set(s.get('required',[]))<=set(x)
  if s.get('additionalProperties') is False:assert set(x)<=set(s.get('properties',{}))
  for k,v in x.items():
   if k in s.get('properties',{}):check(v,s['properties'][k])
 if s.get('type')=='array':
  assert isinstance(x,list) and len(x)>=s.get('minItems',0)
  for a in x:check(a,s['items'])
 if s.get('type')=='string':assert isinstance(x,str) and len(x)>=s.get('minLength',0)
 if 'enum' in s:assert x in s['enum']
 if 'const' in s:assert x==s['const']
check(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert r['context']['previous_runtime_error'] is None
for v in p['variants']:
 f=Path(v['file']);assert f.name==str(f) and f.suffix=='.py'
 source=f.read_text();tree=ast.parse(source);compile(tree,str(f),'exec')
 cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(q,ast.Name) and q.id=='CONFIG' for q in n.targets))
 assert cfg==v['config'] and hashlib.sha256(f.read_bytes()).hexdigest() in v['note']
 assert cfg['timing_mode']=='joint'
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
print('Final proposal schema, evidence IDs, configs, hashes, source compilation and unchanged baseline checks passed.')
print('Four standalone variants ready for host execution. No training or withheld assessment requested.')
PY"

